using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using ImageMagick;
using PdfSharp.Drawing;
using PdfSharp.Pdf;
using PdfSharp.Pdf.IO;
using SkiaSharp;
namespace CremaTools;

public record JobResult(List<string> Files, List<string> Errors, long Before, long After);
public static class FileEngine
{
    public static readonly string[] Images = [".jpg", ".jpeg", ".png", ".webp", ".heic", ".heif", ".avif", ".tif", ".tiff", ".bmp", ".gif"];
    public static bool IsPdf(string file) => Path.GetExtension(file).Equals(".pdf", StringComparison.OrdinalIgnoreCase);
    public static bool IsImage(string file) => Images.Contains(Path.GetExtension(file).ToLowerInvariant());
    public static bool CanHeic => File.Exists(Path.Combine(AppContext.BaseDirectory, "assets", "heif", "heif-enc.exe"));
    public static IEnumerable<(byte[] Data, string Name)> Frames(string file, int dpi = 150, CancellationToken cancel = default) { if (IsPdf(file)) { using var input = File.OpenRead(file); int i = 1; foreach (var bitmap in PDFtoImage.Conversion.ToImages(input, options: new PDFtoImage.RenderOptions(Dpi: dpi))) { using (bitmap) { cancel.ThrowIfCancellationRequested(); using var data = bitmap.Encode(SKEncodedImageFormat.Png, 100); yield return (data.ToArray(), Path.GetFileNameWithoutExtension(file) + " - page " + (i++).ToString("000")); } } } else { if (!IsImage(file)) throw new Exception("Format d’entrée non pris en charge : " + Path.GetExtension(file)); using var image = new MagickImage(file); image.AutoOrient(); image.Strip(); image.Format = MagickFormat.Png; yield return (image.ToByteArray(), Path.GetFileNameWithoutExtension(file)); } }
    static MagickFormat Format(string name) => name switch { "JPEG" => MagickFormat.Jpeg, "PNG" => MagickFormat.Png, "WebP" => MagickFormat.WebP, "HEIC" => MagickFormat.Heic, "TIFF" => MagickFormat.Tiff, "BMP" => MagickFormat.Bmp, "AVIF" => MagickFormat.Avif, _ => throw new Exception("Format de sortie inconnu.") };
    static string Ext(string name) => name switch { "JPEG" => "jpg", "WebP" => "webp", _ => name.ToLowerInvariant() };
    public static void AddImage(PdfDocument pdf, byte[] bytes, double width = 0, double height = 0) { using var stream = new MemoryStream(bytes); using var image = XImage.FromStream(stream); var page = pdf.AddPage(); page.Width = XUnit.FromPoint(width > 0 ? width : 595.28); page.Height = XUnit.FromPoint(height > 0 ? height : 841.89); using var graphics = XGraphics.FromPdfPage(page); double factor = Math.Min((page.Width.Point - 36) / image.PixelWidth, (page.Height.Point - 36) / image.PixelHeight); double w = image.PixelWidth * factor, h = image.PixelHeight * factor; graphics.DrawImage(image, (page.Width.Point - w) / 2, (page.Height.Point - h) / 2, w, h); }
    public static JobResult ConvertFiles(List<string> files, string folder, string target, int quality, bool zip, IProgress<string> progress, CancellationToken cancel)
    {
        var outputs = new List<string>(); var errors = new List<string>(); using var combined = new PdfDocument(); int n = 0; foreach (var file in files)
        {
            cancel.ThrowIfCancellationRequested(); progress.Report($"Conversion {++n}/{files.Count} : {Path.GetFileName(file)}"); try
            {
                if (target.StartsWith("PDF") && IsPdf(file)) { using var original = PdfReader.Open(file, PdfDocumentOpenMode.Import); if (target.Contains("un document")) { foreach (PdfPage p in original.Pages) combined.AddPage(p); } else { using var copy = new PdfDocument(); foreach (PdfPage p in original.Pages) copy.AddPage(p); var outFile = Storage.Unique(folder, Path.GetFileNameWithoutExtension(file) + " - copie.pdf"); copy.Save(outFile); outputs.Add(outFile); } continue; }
                using var separate = new PdfDocument(); foreach (var frame in Frames(file, 150, cancel)) { if (target.StartsWith("PDF")) { AddImage(target.Contains("un document") ? combined : separate, frame.Data); } else { using var image = new MagickImage(frame.Data); image.Quality = (uint)quality; if (target == "JPEG") { image.BackgroundColor = MagickColors.White; image.Alpha(AlphaAction.Remove); } var output = Storage.Unique(folder, frame.Name + "." + Ext(target)); if (target == "HEIC") EncodeHeic(frame.Data, output, quality, cancel); else image.Write(output, Format(target)); outputs.Add(output); } }
                if (target.StartsWith("PDF") && !target.Contains("un document") && separate.PageCount > 0) { var output = Storage.Unique(folder, Path.GetFileNameWithoutExtension(file) + ".pdf"); separate.Save(output); outputs.Add(output); }
            }
            catch (OperationCanceledException) { throw; }
            catch (Exception e) { errors.Add(Path.GetFileName(file) + " : " + e.Message); }
        }
        if (combined.PageCount > 0) { var output = Storage.Unique(folder, "Documents réunis.pdf"); combined.Save(output); outputs.Add(output); }
        if (zip && outputs.Count > 0) outputs.Add(CreateArchive(outputs, folder, false, cancel)); return Result(files, outputs, errors);
    }
    public static JobResult Compress(List<string> files, string folder, string mode, bool zip, IProgress<string> progress, CancellationToken cancel)
    {
        if (mode.StartsWith("Archive")) { var archive = CreateArchive(files, folder, mode.Contains("7z"), cancel); return Result(files, [archive], []); }
        var outputs = new List<string>(); var errors = new List<string>(); int n = 0; foreach (var file in files) { cancel.ThrowIfCancellationRequested(); progress.Report($"Compression {++n}/{files.Count} : {Path.GetFileName(file)}"); try { if (mode.StartsWith("Images")) { if (!IsImage(file)) throw new Exception("Choisissez le mode PDF pour ce fichier."); using var image = new MagickImage(file); image.AutoOrient(); image.Strip(); image.Resize(new MagickGeometry(mode.Contains("Mail") ? 1600u : 2560u, mode.Contains("Mail") ? 1600u : 2560u) { Greater = true }); image.Quality = mode.Contains("Mail") ? 72u : 85u; image.BackgroundColor = MagickColors.White; image.Alpha(AlphaAction.Remove); var output = Storage.Unique(folder, Path.GetFileNameWithoutExtension(file) + " - léger.jpg"); image.Write(output, MagickFormat.Jpeg); outputs.Add(output); } else { if (!IsPdf(file)) throw new Exception("Choisissez le mode Images pour ce fichier."); var output = Storage.Unique(folder, Path.GetFileNameWithoutExtension(file) + " - léger.pdf"); if (mode.Contains("sans perte")) { using (var pdf = PdfReader.Open(file, PdfDocumentOpenMode.Modify)) { pdf.Options.CompressContentStreams = true; pdf.Save(output); } if (new FileInfo(output).Length >= new FileInfo(file).Length) File.Copy(file, output, true); } else { using var pdf = new PdfDocument(); foreach (var frame in Frames(file, 120, cancel)) { using var image = new MagickImage(frame.Data); image.Quality = 65; image.Format = MagickFormat.Jpeg; AddImage(pdf, image.ToByteArray()); } pdf.Save(output); } outputs.Add(output); } } catch (OperationCanceledException) { throw; } catch (Exception e) { errors.Add(Path.GetFileName(file) + " : " + e.Message); } }
        if (zip && outputs.Count > 0) outputs.Add(CreateArchive(outputs, folder, false, cancel)); return Result(files, outputs, errors);
    }
    static JobResult Result(List<string> inputs, List<string> outputs, List<string> errors) => new(outputs, errors, inputs.Where(File.Exists).Sum(f => new FileInfo(f).Length), outputs.Where(File.Exists).Where(f => outputs.Count == 1 || !f.EndsWith(".zip")).Sum(f => new FileInfo(f).Length));
    public static string CreateArchive(List<string> files, string folder, bool seven, CancellationToken cancel)
    {
        if (files.Count == 0) throw new Exception("Ajoutez des fichiers."); var output = Storage.Unique(folder, "Documents - " + DateTime.Now.ToString("yyyy-MM-dd") + (seven ? ".7z" : ".zip")); if (!seven) { using var zip = ZipFile.Open(output, ZipArchiveMode.Create); var names = new HashSet<string>(StringComparer.OrdinalIgnoreCase); foreach (var file in files) { cancel.ThrowIfCancellationRequested(); string name = Path.GetFileName(file); int n = 2; while (!names.Add(name)) name = Path.GetFileNameWithoutExtension(file) + " (" + (n++) + ")" + Path.GetExtension(file); zip.CreateEntryFromFile(file, name, CompressionLevel.SmallestSize); } return output; }
        string temp = Path.Combine(Path.GetTempPath(), "crematools-archive-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(temp); try { foreach (var file in files) { cancel.ThrowIfCancellationRequested(); File.Copy(file, Storage.Unique(temp, Path.GetFileName(file))); } var start = new ProcessStartInfo(Path.Combine(AppContext.BaseDirectory, "assets", "7zr.exe")) { UseShellExecute = false, CreateNoWindow = true, WorkingDirectory = temp, RedirectStandardOutput = true, RedirectStandardError = true }; foreach (var arg in new[] { "a", "-t7z", "-mx=7", output, ".\\*" }) start.ArgumentList.Add(arg); using var process = Process.Start(start) ?? throw new Exception("Impossible de lancer 7z."); var stdout = process.StandardOutput.ReadToEndAsync(); var stderr = process.StandardError.ReadToEndAsync(); while (!process.WaitForExit(150)) { if (cancel.IsCancellationRequested) { process.Kill(true); cancel.ThrowIfCancellationRequested(); } } Task.WaitAll(stdout, stderr); if (process.ExitCode != 0) throw new Exception("7z : " + stderr.Result); return output; } catch { if (File.Exists(output)) File.Delete(output); throw; } finally { Directory.Delete(temp, true); }
    }
    public static void EncodeHeic(byte[] input, string destination, int quality, CancellationToken cancel) { var temp = Path.Combine(Path.GetTempPath(), "crematools-heic-" + Guid.NewGuid().ToString("N") + ".png"); File.WriteAllBytes(temp, input); try { var start = new ProcessStartInfo(Path.Combine(AppContext.BaseDirectory, "assets", "heif", "heif-enc.exe")) { UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true }; foreach (var arg in new[] { "-q", quality.ToString(), "--color-profile", "compatible", "-o", destination, temp }) start.ArgumentList.Add(arg); using var process = Process.Start(start) ?? throw new Exception("Impossible de lancer l’encodeur HEIC."); var stdout = process.StandardOutput.ReadToEndAsync(); var stderr = process.StandardError.ReadToEndAsync(); while (!process.WaitForExit(150)) { if (cancel.IsCancellationRequested) { process.Kill(true); cancel.ThrowIfCancellationRequested(); } } Task.WaitAll(stdout, stderr); if (process.ExitCode != 0 || !File.Exists(destination)) throw new Exception("HEIC : " + stderr.Result); } catch { if (File.Exists(destination)) File.Delete(destination); throw; } finally { File.Delete(temp); } }
}
